# Turns the two CSV files in data/ into data.js, which the web page loads.
# Run from the project folder:  python python/build_data.py
import csv, json

def rows(path, keep):
    with open(path, encoding="utf-8-sig") as f:
        return [r[:keep] for r in list(csv.reader(f))[1:]]

def fmt(name, items):
    body = ",\n".join(json.dumps(r, ensure_ascii=False) for r in items)
    return f"const {name} = [\n{body}\n];\n"

header = (
    "// Word and sentence data. Generated by python/build_data.py, do not edit by hand.\n"
    "// Source: Ali, Grimm and Bodomo (2021), A Dictionary and Grammatical Sketch of Dagaare,\n"
    "// Language Science Press, CC BY 4.0. Cleaned and reformatted for this app.\n"
)
words = rows("data/dagaare-words.csv", 3)      # Dagaare, English, part of speech
phrases = rows("data/dagaare-phrases.csv", 2)  # Dagaare, English
with open("data.js", "w", encoding="utf-8") as f:
    f.write(header + fmt("DATA", words) + fmt("PHRASES", phrases))
print(len(words), "words and", len(phrases), "sentences written to data.js")
